class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Segment tree size: 2 * n
        tree = [0] * (2 * n)

        # Initialize leaves
        for i in range(n):
            tree[n + i] = baskets[i]

        # Build internal nodes
        for i in range(n - 1, 0, -1):
            tree[i] = max(tree[2*i], tree[2*i+1])

        def find_first(val):
            """
            Finds the smallest index i in [0, n-1] such that the basket at i has capacity >= val.
            Returns -1 if no such basket exists.
            """
            curr = 1
            while True:
                if curr >= n:
                    if tree[curr] >= val:
                        return curr - n
                    else:
                        return -1

                if tree[2*curr] >= val:
                    curr = 2*curr
                elif tree[2*curr+1] >= val and 2*curr+1 < 2*n:
                    curr = 2*curr+1
                else:
                    return -1

                # Safety break to avoid infinite loop (should not be needed due to tree structure)
                if curr > 2 * n:
                    return -1

        def update(pos):
            """
            Marks the basket at original index 'pos' as used by setting its capacity to 0.
            Updates the segment tree accordingly.
            """
            pos += n
            tree[pos] = 0
            while pos > 1:
                pos //= 2
                tree[pos] = max(tree[2*pos], tree[2*pos+1])

        unplaced = 0
        for f in fruits:
            idx = find_first(f)
            if idx != -1:
                update(idx)
            else:
                unplaced += 1

        return unplaced

