            # If the value doesn't exist elsewhere, return -1
            if not indices:
                answer.append(-1)
                continue

            # Find the position of the current index in the sorted list of indices
            pos_in_list = bisect.bisect_left(indices, q_idx)

            min_dist = float('inf')

            # Identify candidate indices that could be the nearest
            candidates = []

            # 1. The immediate next index in the sorted list
            if pos_in_list + 1 < len(indices):
                candidates.append(indices[pos_in_list + 1])

            # 2. The immediate previous index in the sorted list
            if pos_in_list > 0:
                candidates.append(indices[pos_in_list - 1])

            # 3. The first index in the list (handles wrap-around from end)
            candidates.append(indices[0])

            # 4. The last index in the list (handles wrap-around to start)
            candidates.append(indices[-1])

