        n = len(properties)
        # Build adjacency matrix or list for the graph
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection = len(set_i & set_j)

