            second_digit = int(s[i+1])

            # Check if digits are different
            if first_digit == second_digit:
                continue

            # Check if each digit appears exactly as many times as its numeric value
            if freq[first_digit] == first_digit and freq[second_digit] == second_digit:
                return s[i:i+2]

        return ""

from typing import List

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            # Collect the values at indices i-k and i+k if they exist
            neighbors = []
            if i - k >= 0:
                neighbors.append(nums[i - k])
            if i + k < n:
                neighbors.append(nums[i + k])

            # If no neighbors exist, the element is good
            if not neighbors:
                total_sum += nums[i]
            else:
                # Element is good if strictly greater than all neighbors
                # This is equivalent to being greater than the maximum neighbor
                if nums[i] > max(neighbors):
                    total_sum += nums[i]

        return total_sum

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        from itertools import permutations
        seen = set()
        for p in permutations(digits, 3):
            if p[0] == 0:
                continue
            num = p[0]*100 + p[1]*10 + p[2]
            if num % 2 == 0:
                seen.add(num)
        return len(seen)

class Solution:
    def reverseDegree(self, s: str) -> int:
        # Map each character to its reversed alphabet index: 'a'->26, 'b'->25, ..., 'z'->1
        char_to_val = {chr(ord('a') + i): 27 - i for i in range(26)}

        total = 0
        for idx, char in enumerate(s, start=1):  # 1-indexed position
            total += char_to_val[char] * idx

        return total
